INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 1, 126401, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", "2023/09/22 14:59:59", 0.0, "クローチェ", 1.47, 1, 1, "2023/06/30 12:00:00", 10001, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 1, 126401, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", "2023/09/22 14:59:59", 0.0, "クローチェ", 2.15, 2, 2, "2023/06/30 12:00:00", 10002, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 1, 126501, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", "2023/09/22 14:59:59", 0.0, "ライラエル", 0.0, 2, 1, "2023/06/30 12:00:00", 10003, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 1, 126501, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", "2023/09/22 14:59:59", 0.0, "ライラエル", 0.0, 1, 2, "2023/06/30 12:00:00", 10004, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 2, 127702, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", "2023/12/22 14:59:59", 0.0, "リンド", 0.0, 2, 1, "2023/09/15 15:00:00", 10005, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 2, 127702, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", "2023/12/22 14:59:59", 0.0, "リンド", 0.0, 2, 2, "2023/09/15 15:00:00", 10006, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 2, 127802, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", "2023/12/22 14:59:59", 0.0, "ヴルム", 0.0, 1, 1, "2023/09/15 15:00:00", 10007, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 2, 127802, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", "2023/12/22 14:59:59", 0.0, "ヴルム", 6.5, 2, 2, "2023/09/15 15:00:00", 10008, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 3, 129602, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", "2024/03/22 14:59:59", 0.0, "アネモネ", 0.0, 2, 1, "2023/12/15 15:00:00", 10009, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 3, 129602, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", "2024/03/22 14:59:59", 0.0, "アネモネ", 0.0, 2, 2, "2023/12/15 15:00:00", 10010, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 3, 129701, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", "2024/03/22 14:59:59", 0.0, "ネフィ=ネラ", 0.0, 1, 1, "2023/12/15 15:00:00", 10011, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 3, 129701, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", "2024/03/22 14:59:59", 0.0, "ネフィ=ネラ", 6.2, 2, 2, "2023/12/15 15:00:00", 10012, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 4, 130301, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", "2024/06/22 14:59:59", 0.0, "カノン", 3.1, 3, 1, "2024/03/15 15:00:00", 10013, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 4, 130301, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", "2024/06/22 14:59:59", 0.0, "カノン", 6.15, 3, 2, "2024/03/15 15:00:00", 10014, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 4, 130401, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", "2024/06/22 14:59:59", 0.0, "ナーナ", 0.0, 2, 1, "2024/03/15 15:00:00", 10015, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 4, 130401, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", "2024/06/22 14:59:59", 0.0, "ナーナ", 3.35, 2, 2, "2024/03/15 15:00:00", 10016, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 5, 130502, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", "2024/09/22 14:59:59", 0.0, "ホウオウ", 0.0, 1, 1, "2024/06/15 15:00:00", 10017, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 5, 130502, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", "2024/09/22 14:59:59", 0.0, "ホウオウ", 3.18, 2, 2, "2024/06/15 15:00:00", 10018, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 5, 130503, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", "2024/09/22 14:59:59", 0.0, "ホウオウ", 0.0, 4, 3, "2024/06/15 15:00:00", 10019, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 5, 123301, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", "2024/09/22 14:59:59", 0.0, "ネア", 4.9, 1, 1, "2024/06/15 15:00:00", 10020, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 5, 123301, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", "2024/09/22 14:59:59", 0.0, "ネア", 4.8, 1, 2, "2024/06/15 15:00:00", 10021, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 6, 133301, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", "2024/12/22 14:59:59", 0.0, "カリザ", 4.922, 3, 1, "2024/09/15 15:00:00", 10022, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 6, 133301, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", "2024/12/22 14:59:59", 0.0, "カリザ", 9.638, 3, 2, "2024/09/15 15:00:00", 10023, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 6, 133401, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", "2024/12/22 14:59:59", 0.0, "ミーア", 2.88, 1, 1, "2024/09/15 15:00:00", 10024, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 6, 133401, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", "2024/12/22 14:59:59", 0.0, "ミーア", 4.818, 5, 2, "2024/09/15 15:00:00", 10025, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 7, 133002, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", "2025/03/22 14:59:59", 0.0, "グレイス", 1.78, 2, 1, "2024/12/15 15:00:00", 10026, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 7, 133002, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", "2025/03/22 14:59:59", 0.0, "グレイス", 6.15, 1, 2, "2024/12/15 15:00:00", 10027, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 7, 133102, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", "2025/03/22 14:59:59", 0.0, "ヴァイオレット", 4.28, 6, 1, "2024/12/15 15:00:00", 10028, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 7, 133102, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", "2025/03/22 14:59:59", 0.0, "ヴァイオレット", 0.0, 1, 2, "2024/12/15 15:00:00", 10029, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 8, 136902, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", "2025/06/23 14:59:59", 0.0, "ルルィ", 5.53, 2, 1, "2025/03/15 15:00:00", 10030, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 8, 136902, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", "2025/06/23 14:59:59", 0.0, "ルルィ", 6.05, 9, 2, "2025/03/15 15:00:00", 10031, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 8, 137001, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", "2025/06/23 14:59:59", 0.0, "デュラン", 0.0, 2, 1, "2025/03/15 15:00:00", 10032, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 8, 137001, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", "2025/06/23 14:59:59", 0.0, "デュラン", 0.0, 2, 2, "2025/03/15 15:00:00", 10033, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 9, 135902, "おう\n好きなもん持ってきな", "2025/09/23 14:59:59", 0.0, "サツキ", 0.0, 2, 1, "2025/06/16 15:00:00", 10034, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 9, 135902, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", "2025/09/23 14:59:59", 0.0, "サツキ", 4.935, 1, 2, "2025/06/16 15:00:00", 10035, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 9, 135802, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", "2025/09/23 14:59:59", 0.0, "ユキノ", 7.441, 2, 1, "2025/06/16 15:00:00", 10036, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 9, 135802, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", "2025/09/23 14:59:59", 0.0, "ユキノ", 0.0, 7, 2, "2025/06/16 15:00:00", 10037, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 10, 130901, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", "2025/12/22 14:59:59", 0.0, "クルル", 2.295, 2, 1, "2025/09/16 15:00:00", 10038, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 10, 130901, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", "2025/12/22 14:59:59", 0.0, "クルル", 6.281, 1, 2, "2025/09/16 15:00:00", 10039, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 10, 137701, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", "2025/12/22 14:59:59", 0.0, "ヴォルガーノ", 5.549, 2, 1, "2025/09/16 15:00:00", 10040, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 10, 137701, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", "2025/12/22 14:59:59", 0.0, "ヴォルガーノ", 2.64, 3, 2, "2025/09/16 15:00:00", 10041, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 11, 132801, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", "2026/03/23 11:59:59", 0.0, "ライラエル", 7.642, 7, 1, "2025/12/15 15:00:00", 10042, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 11, 132802, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", "2026/03/23 11:59:59", 0.0, "ライラエル", 0.0, 1, 2, "2025/12/15 15:00:00", 10043, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 11, 134502, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", "2026/03/23 11:59:59", 0.0, "クローチェ", 0.0, 1, 1, "2025/12/15 15:00:00", 10044, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 11, 134501, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", "2026/03/23 11:59:59", 0.0, "クローチェ", 3.72, 2, 2, "2025/12/15 15:00:00", 10045, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 12, 138201, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", "2026/06/22 11:59:59", 0.0, "ネフィ＝ネラ", 4.991, 2, 1, "2026/03/16 12:00:00", 10046, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 12, 138201, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", "2026/06/22 11:59:59", 0.0, "ネフィ＝ネラ", 3.877, 1, 2, "2026/03/16 12:00:00", 10047, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 12, 136001, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", "2026/06/22 11:59:59", 0.0, "アラクネ", 1.71, 4, 1, "2026/03/16 12:00:00", 10048, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 12, 136001, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", "2026/06/22 11:59:59", 0.0, "アラクネ", 5.32, 5, 2, "2026/03/16 12:00:00", 10049, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 13, 135401, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", "2026/09/22 11:59:59", 0.0, "アネモネ", 3.727, 9, 1, "2026/06/15 12:00:00", 10050, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 13, 135401, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", "2026/09/22 11:59:59", 0.0, "アネモネ", 7.213, 7, 2, "2026/06/15 12:00:00", 10051, -470.0, 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 13, 135301, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", "2026/09/22 11:59:59", 0.0, "クリア", 1.874, 1, 1, "2026/06/15 12:00:00", 10052, -470.0, 2002);
