INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 14, 138001, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", "2026/12/22 11:59:59", 0.0, "ヴァイオレット", 4.215, 2, 1, "2026/09/15 12:00:00", 10054, -470.0, 2002);
